  ('icd9cm', 'http://hl7.org/fhir/sid/icd-9-cm', '*', 'ICD-9 CM (peta layanan klinik)', 'SATUSEHAT Standar Terminologi v12.0 (2026-10-31)',
   'https://satusehat.kemkes.go.id/platform/docs/id/fhir/resources/procedure/', '2026-11-17'),
  ('kfa', 'http://sys-ids.kemkes.go.id/kfa', '*', 'KFA (kode obat pada resep)', 'SATUSEHAT Standar Terminologi v12.0 (2026-10-31)',
