-- A staff member's current practitioner IHS id (null when none is linked).
CREATE FUNCTION public.satusehat_ihs(p_tenant uuid, p_staff uuid) RETURNS text
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT l.ihs_practitioner_id FROM public.satusehat_practitioner_links l WHERE l.tenant_id = p_tenant AND l.staff_id = p_staff AND l.ended_at IS NULL
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_ihs(uuid, uuid) FROM PUBLIC;--> statement-breakpoint

-- Materialize every link of a revision (plan §2). Each source row is pinned once per link revision with every value its builder emits (codes,
-- register / map rows, practitioner and patient references, times) and a fingerprint; a link whose inputs are incomplete (no KFA code, no
-- ICD-9 CM map, no practitioner IHS id) is held per link without a pin, and pinned on the first materialization at which it is sendable. A
-- confirmed link advances without a send ONLY on fingerprint equality with its confirmed revision (addendum r2); otherwise it is queued for
-- an update behind any unresolved write. Production holds a link whose pinned register or map row is unvalidated and releases it once that
-- pinned row is validated. A source gone from the revision: withdrawal_pending when sent, held otherwise. Organization binding as before.
CREATE OR REPLACE FUNCTION public.satusehat_materialize(o public.satusehat_outbox, p_env text, p_org text, p_ctx jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  rv public.record_versions;
  r record;
  l public.satusehat_links;
  v_fp text;
  v_reg uuid;
  v_valid boolean;
  v_pinned boolean;
  v_enc jsonb := jsonb_build_array(jsonb_build_array('Encounter', 'visit'));
BEGIN
  SELECT * INTO rv FROM public.record_versions x WHERE x.tenant_id = o.tenant_id AND x.id = o.exam_version_id;
  SELECT s.id INTO v_reg FROM public.satusehat_code_systems s WHERE s.kind = 'icd10' AND s.code = '*' AND s.effective_to IS NULL;
  FOR r IN
    SELECT 'Encounter'::text AS fhir_type, 'visit'::text AS local_key,
           jsonb_build_object('visit_id', o.visit_id, 'class', 'AMB', 'organization', p_org) || p_ctx AS m, NULL::text AS hold
    UNION ALL
    SELECT 'Condition', 'exam:' || c, jsonb_build_object('code', c, 'system', 'http://hl7.org/fhir/sid/icd-10', 'register_id', v_reg, 'rank', ord,
           'organization', p_org, 'patient_ihs', p_ctx ->> 'patient_ihs', 'visit_id', o.visit_id, 'parents', v_enc), NULL
      FROM jsonb_array_elements_text(rv.content -> 'icd10_codes') WITH ORDINALITY AS t(c, ord)
    UNION ALL
    SELECT 'Observation', 'exam:' || x.key,
           jsonb_build_object('field', x.key, 'code', s.code, 'display', s.display, 'register_id', s.id,
             'value', CASE WHEN x.key = 'suhu_c10' THEN (x.value #>> '{}')::numeric / 10 ELSE (x.value #>> '{}')::numeric END, 'unit', u.unit, 'ucum', u.ucum,
             'organization', p_org, 'patient_ihs', p_ctx ->> 'patient_ihs', 'practitioner_ihs', p_ctx ->> 'practitioner_ihs',
             'effective', p_ctx ->> 'in_progress_at', 'visit_id', o.visit_id, 'parents', v_enc),
           CASE WHEN s.id IS NULL OR u.ucum IS NULL THEN 'terminology_unmapped' END
      FROM jsonb_each(coalesce(rv.content -> 'vitals', '{}'::jsonb)) x
      LEFT JOIN public.satusehat_code_systems s ON s.kind = 'loinc' AND s.local_field = x.key AND s.effective_to IS NULL
      LEFT JOIN (VALUES ('td_sistolik', 'mmHg', 'mm[Hg]'), ('td_diastolik', 'mmHg', 'mm[Hg]'), ('nadi', 'beats/minute', '/min'), ('suhu_c10', 'C', 'Cel'),
                        ('berat_kg', 'kg', 'kg')) u(field, unit, ucum) ON u.field = x.key
    UNION ALL
    SELECT 'Procedure', 'exec:' || te.id,
           jsonb_build_object('execution_id', te.id, 'code', mp.code, 'display', mp.display, 'map_id', mp.id, 'register_id', s9.id,
             'organization', p_org, 'patient_ihs', p_ctx ->> 'patient_ihs', 'practitioner_ihs', public.satusehat_ihs(te.tenant_id, te.performer_staff_id),
             'start', te.started_at, 'end', te.finished_at, 'parents', v_enc),
           CASE WHEN mp.id IS NULL OR s9.id IS NULL THEN 'terminology_unmapped'
                WHEN public.satusehat_ihs(te.tenant_id, te.performer_staff_id) IS NULL THEN 'practitioner_unresolved' END
      FROM public.treatment_executions te
      JOIN public.plan_items pi ON pi.tenant_id = te.tenant_id AND pi.id = te.plan_item_id
      JOIN public.catalog_versions cv ON cv.tenant_id = pi.tenant_id AND cv.id = pi.catalog_version_id
      LEFT JOIN public.satusehat_code_maps mp ON mp.tenant_id = te.tenant_id AND mp.item_id = cv.item_id AND mp.kind = 'icd9cm' AND mp.effective_to IS NULL
      LEFT JOIN public.satusehat_code_systems s9 ON s9.kind = 'icd9cm' AND s9.code = '*' AND s9.effective_to IS NULL
     WHERE te.tenant_id = o.tenant_id AND te.visit_id = o.visit_id AND te.state = 'finished' AND te.counted
    UNION ALL
    SELECT 'Medication', 'med:' || it.id, jsonb_build_object('item_id', it.id, 'kfa', it.kfa_code, 'register_id', sk.id, 'organization', p_org),
           CASE WHEN it.kfa_code IS NULL OR sk.id IS NULL THEN 'terminology_unmapped' END
      FROM public.prescription_items it
      JOIN public.prescriptions pr ON pr.tenant_id = it.tenant_id AND pr.id = it.prescription_id AND pr.state = 'signed'
      LEFT JOIN public.satusehat_code_systems sk ON sk.kind = 'kfa' AND sk.code = '*' AND sk.effective_to IS NULL
     WHERE it.tenant_id = o.tenant_id AND it.visit_id = o.visit_id AND it.removed_at IS NULL
    UNION ALL
    SELECT 'MedicationRequest', 'mreq:' || it.id,
           jsonb_build_object('item_id', it.id, 'prescription_id', pr.id, 'signa', it.signa, 'quantity', it.quantity, 'authored_on', pr.signed_at,
             'organization', p_org, 'patient_ihs', p_ctx ->> 'patient_ihs', 'practitioner_ihs', public.satusehat_ihs(pr.tenant_id, pr.prescriber_staff_id),
             'parents', v_enc || jsonb_build_array(jsonb_build_array('Medication', 'med:' || it.id))),
           CASE WHEN public.satusehat_ihs(pr.tenant_id, pr.prescriber_staff_id) IS NULL THEN 'practitioner_unresolved' END
      FROM public.prescription_items it
      JOIN public.prescriptions pr ON pr.tenant_id = it.tenant_id AND pr.id = it.prescription_id AND pr.state = 'signed'
     WHERE it.tenant_id = o.tenant_id AND it.visit_id = o.visit_id AND it.removed_at IS NULL
    UNION ALL
    SELECT 'MedicationDispense', 'mdisp:' || d.id,
           jsonb_build_object('dispensing_id', d.id, 'item_id', it.id, 'quantity', d.quantity, 'handed_over', d.handed_at,
             'organization', p_org, 'patient_ihs', p_ctx ->> 'patient_ihs', 'practitioner_ihs', public.satusehat_ihs(d.tenant_id, d.handed_by),
             'parents', v_enc || jsonb_build_array(jsonb_build_array('Medication', 'med:' || it.id), jsonb_build_array('MedicationRequest', 'mreq:' || it.id))),
           CASE WHEN public.satusehat_ihs(d.tenant_id, d.handed_by) IS NULL THEN 'practitioner_unresolved' END
      FROM public.dispensings d
      JOIN public.prescription_items it ON it.tenant_id = d.tenant_id AND it.id = d.prescription_item_id AND it.removed_at IS NULL
      JOIN public.prescriptions pr ON pr.tenant_id = it.tenant_id AND pr.id = it.prescription_id AND pr.state = 'signed'
     WHERE d.tenant_id = o.tenant_id AND d.visit_id = o.visit_id AND d.state = 'handed'
  LOOP
    -- the rank lives in the Encounter's diagnosis list, not in the Condition: it is pinned but not part of the Condition's content
    v_fp := encode(sha256(convert_to((r.m - 'rank')::text, 'UTF8')), 'hex');
    SELECT * INTO l FROM public.satusehat_links x
     WHERE x.tenant_id = o.tenant_id AND x.environment = p_env AND x.fhir_type = r.fhir_type AND x.visit_id = o.visit_id AND x.local_key = r.local_key FOR UPDATE;
    IF l.id IS NULL THEN
      INSERT INTO public.satusehat_links (tenant_id, branch_id, environment, visit_id, fhir_type, local_key, organization_id, current_revision, status, status_reason)
      VALUES (o.tenant_id, o.branch_id, p_env, o.visit_id, r.fhir_type, r.local_key, p_org, o.revision,
              CASE WHEN r.hold IS NULL THEN 'queued' ELSE 'held' END, r.hold) RETURNING * INTO l;
    ELSIF l.current_revision < o.revision THEN
      IF l.status = 'confirmed' AND v_fp = (SELECT lr.fingerprint FROM public.satusehat_link_revisions lr
                                              WHERE lr.tenant_id = l.tenant_id AND lr.link_id = l.id AND lr.revision = l.confirmed_revision) THEN
        UPDATE public.satusehat_links SET current_revision = o.revision, confirmed_revision = o.revision, updated_at = clock_timestamp()
         WHERE tenant_id = l.tenant_id AND id = l.id;
      ELSIF l.status IN ('confirmed','held','queued') THEN
        UPDATE public.satusehat_links SET current_revision = o.revision, status = 'queued', status_reason = NULL, next_at = clock_timestamp(), updated_at = clock_timestamp()
         WHERE tenant_id = l.tenant_id AND id = l.id;
      ELSE
        -- failed / exception / outcome_unknown / withdrawal_pending: the barrier holds; the revision moves forward and waits behind it
        UPDATE public.satusehat_links SET current_revision = o.revision, updated_at = clock_timestamp() WHERE tenant_id = l.tenant_id AND id = l.id;
      END IF;
    END IF;
    SELECT * INTO l FROM public.satusehat_links x WHERE x.tenant_id = o.tenant_id AND x.id = l.id;
    v_pinned := EXISTS (SELECT 1 FROM public.satusehat_link_revisions lr WHERE lr.tenant_id = l.tenant_id AND lr.link_id = l.id AND lr.revision = l.current_revision);
    IF r.hold IS NULL OR v_pinned THEN
      INSERT INTO public.satusehat_link_revisions (tenant_id, link_id, revision, exam_version_id, materialized, fingerprint, organization_id)
      VALUES (o.tenant_id, l.id, l.current_revision, o.exam_version_id, r.m, v_fp, p_org) ON CONFLICT DO NOTHING;
      -- production sends only validated terminology: decided by the register / map rows PINNED for the link's current revision
      SELECT (rg.id IS NULL OR rg.validated) AND (mp.id IS NULL OR mp.validated) INTO v_valid
        FROM public.satusehat_link_revisions lr
        LEFT JOIN public.satusehat_code_systems rg ON rg.id = (lr.materialized ->> 'register_id')::uuid
        LEFT JOIN public.satusehat_code_maps mp ON mp.tenant_id = lr.tenant_id AND mp.id = (lr.materialized ->> 'map_id')::uuid
       WHERE lr.tenant_id = l.tenant_id AND lr.link_id = l.id AND lr.revision = l.current_revision;
      IF p_env = 'production' AND NOT coalesce(v_valid, false) THEN
        UPDATE public.satusehat_links SET status = 'held', status_reason = 'mapping_unvalidated', updated_at = clock_timestamp()
         WHERE tenant_id = l.tenant_id AND id = l.id AND status = 'queued';
      ELSE
        UPDATE public.satusehat_links SET status = 'queued', status_reason = NULL, next_at = clock_timestamp(), updated_at = clock_timestamp()
         WHERE tenant_id = l.tenant_id AND id = l.id AND status = 'held'
           AND status_reason IN ('mapping_unvalidated','terminology_unmapped','practitioner_unresolved');
      END IF;
    ELSE
      UPDATE public.satusehat_links SET status = 'held', status_reason = r.hold, updated_at = clock_timestamp()
       WHERE tenant_id = l.tenant_id AND id = l.id AND status = 'queued';
    END IF;
  END LOOP;
  -- a source gone from this revision (no guide rule for withdrawal: manual)
  UPDATE public.satusehat_links x SET status = 'withdrawal_pending', status_reason = 'source_removed', updated_at = clock_timestamp()
   WHERE x.tenant_id = o.tenant_id AND x.environment = p_env AND x.visit_id = o.visit_id AND x.fhir_type <> 'Encounter' AND x.status IN ('confirmed','queued','held')
     AND x.current_revision < o.revision AND x.remote_id IS NOT NULL;
  UPDATE public.satusehat_links x SET status = 'held', status_reason = 'source_removed', updated_at = clock_timestamp()
   WHERE x.tenant_id = o.tenant_id AND x.environment = p_env AND x.visit_id = o.visit_id AND x.fhir_type <> 'Encounter' AND x.status = 'queued'
     AND x.current_revision < o.revision AND x.remote_id IS NULL;
  -- organization binding (plan §6, r2 P1-3)
  UPDATE public.satusehat_links x SET status = 'exception', status_reason = 'organization_changed', updated_at = clock_timestamp()
   WHERE x.tenant_id = o.tenant_id AND x.environment = p_env AND x.visit_id = o.visit_id AND x.organization_id <> p_org
     AND x.status IN ('queued','held','confirmed','outcome_unknown');
END
$$;--> statement-breakpoint

-- Release the lease (plan §4): done when no link of the visit can still progress — queued or outcome_unknown with every ancestor (the pinned
-- `parents`: Encounter; Medication; MedicationRequest) still queued, sending, outcome_unknown or confirmed; otherwise queued again for the
-- earliest due one. A link behind an ancestor in an exception, failure or hold waits for a person (Kirim Ulang adds a new item).
CREATE OR REPLACE FUNCTION public.satusehat_release(p_item uuid, p_gen integer, p_now timestamptz DEFAULT NULL) RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  v_now timestamptz := coalesce(p_now, clock_timestamp());
  o public.satusehat_outbox;
  v_next timestamptz;
BEGIN
  PERFORM public.satusehat_unbound();
  o := public.satusehat_fenced(p_item, p_gen, v_now);
  IF o.id IS NULL THEN RETURN 'stale'; END IF;
  UPDATE public.satusehat_links SET status = 'outcome_unknown', check_after = v_now, updated_at = v_now
   WHERE tenant_id = o.tenant_id AND visit_id = o.visit_id AND status = 'sending';
  SELECT min(CASE WHEN l.status = 'queued' THEN l.next_at ELSE l.check_after END) INTO v_next FROM public.satusehat_links l
   WHERE l.tenant_id = o.tenant_id AND l.environment = public.satusehat_env() AND l.visit_id = o.visit_id AND l.status IN ('queued','outcome_unknown')
     AND NOT EXISTS (
       SELECT 1 FROM public.satusehat_link_revisions lr, jsonb_array_elements(coalesce(lr.materialized -> 'parents', '[]'::jsonb)) pa
        WHERE lr.tenant_id = l.tenant_id AND lr.link_id = l.id AND lr.revision = l.current_revision
          AND NOT EXISTS (SELECT 1 FROM public.satusehat_links a WHERE a.tenant_id = l.tenant_id AND a.environment = l.environment AND a.visit_id = l.visit_id
                            AND a.fhir_type = pa ->> 0 AND a.local_key = pa ->> 1 AND a.status IN ('confirmed','queued','sending','outcome_unknown')));
  IF v_next IS NULL THEN
    UPDATE public.satusehat_outbox SET state = 'done', lease_until = NULL, finished_at = v_now WHERE tenant_id = o.tenant_id AND id = o.id;
    RETURN 'done';
  END IF;
  UPDATE public.satusehat_outbox SET state = 'queued', lease_until = NULL, next_at = greatest(v_next, v_now) WHERE tenant_id = o.tenant_id AND id = o.id;
  RETURN 'queued';
END
$$;--> statement-breakpoint

-- Medication has no search (the guide documents only Detail Data): an uncertain Medication create is never searched and never re-created
-- automatically — it becomes an exception (reconcile_unresolved) for a person; Kirim Ulang creates anew, audited. Fenced.
CREATE FUNCTION public.satusehat_no_search(p_item uuid, p_gen integer, p_link uuid, p_now timestamptz DEFAULT NULL) RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  o public.satusehat_outbox;
  l public.satusehat_links;
BEGIN
  PERFORM public.satusehat_unbound();
  o := public.satusehat_fenced(p_item, p_gen, coalesce(p_now, clock_timestamp()));
  IF o.id IS NULL THEN RETURN 'stale'; END IF;
  SELECT * INTO l FROM public.satusehat_links x WHERE x.tenant_id = o.tenant_id AND x.id = p_link AND x.visit_id = o.visit_id FOR UPDATE;
  IF l.id IS NULL OR l.fhir_type <> 'Medication' OR l.status <> 'outcome_unknown' OR l.remote_id IS NOT NULL THEN
    RAISE EXCEPTION 'ERR_VERSION_CONFLICT: only an uncertain Medication create has no search' USING ERRCODE = '40001';
  END IF;
  UPDATE public.satusehat_links SET status = 'exception', status_reason = 'reconcile_unresolved', updated_at = clock_timestamp()
   WHERE tenant_id = l.tenant_id AND id = l.id;
  RETURN 'exception';
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_no_search(uuid, integer, uuid, timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION public.satusehat_no_search(uuid, integer, uuid, timestamptz) TO clinic_app;--> statement-breakpoint

-- Requeue (a new resend item) the visits whose links wait on something just resolved; only visits whose last item is finished or held.
CREATE FUNCTION public.satusehat_requeue_links(p_tenant uuid, p_reason text, p_visits uuid[]) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  v record;
BEGIN
  FOR v IN SELECT DISTINCT ON (x.visit_id) x.id, x.state FROM public.satusehat_outbox x
            WHERE x.tenant_id = p_tenant AND x.visit_id = ANY (p_visits)
              AND EXISTS (SELECT 1 FROM public.satusehat_links l WHERE l.tenant_id = x.tenant_id AND l.visit_id = x.visit_id AND l.status = 'held' AND l.status_reason = p_reason)
            ORDER BY x.visit_id, x.revision DESC, x.created_at DESC LOOP
    IF v.state IN ('done','held') THEN
      PERFORM public.satusehat_requeue(p_tenant, v.id);
    END IF;
  END LOOP;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_requeue_links(uuid, text, uuid[]) FROM PUBLIC;--> statement-breakpoint

-- Practitioner IHS id (DEC-113 (6)) — re-created: increment 2 also requeues visits whose Procedure / MedicationRequest / MedicationDispense
-- link waits on this staff member's IHS id (performer, prescriber, dispenser). Replay authorized first (review r1 P2-8), as before.
CREATE OR REPLACE FUNCTION public.satusehat_practitioner_link_set(p_key text, p_staff uuid, p_ihs text, p_source text) RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  a record := public.satusehat_actor(ARRAY['owner','facility_head']);
  x public.satusehat_practitioner_links;
  v_id uuid;
  o record;
BEGIN
  IF coalesce(p_key, '') !~ '^[A-Za-z0-9_.:-]{8,128}$' OR coalesce(p_ihs, '') !~ '^[A-Za-z0-9-]{3,64}$' OR p_source NOT IN ('lookup','manual') THEN
    RAISE EXCEPTION 'ERR_INVALID_INPUT: practitioner' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO x FROM public.satusehat_practitioner_links l WHERE l.tenant_id = a.tenant_id AND l.command_key = p_key;
  -- a replay answers only an actor who may act on that staff member now (review r1 P2-8): authorize first, then replay
  IF NOT EXISTS (SELECT 1 FROM public.staff_branches sb WHERE sb.tenant_id = a.tenant_id AND sb.staff_id = coalesce(x.staff_id, p_staff)
                   AND sb.role IN ('doctor','nurse','therapist','pharmacist','facility_head')
                   AND (a.role = 'owner' OR public.app_branch_allowed(sb.branch_id) AND (a.branch_id IS NULL OR sb.branch_id = a.branch_id))) THEN
    RAISE EXCEPTION 'ERR_NOT_FOUND: staff not found' USING ERRCODE = 'P0002';
  END IF;
  IF x.id IS NOT NULL THEN RETURN x.id; END IF;
  UPDATE public.satusehat_practitioner_links SET ended_at = clock_timestamp() WHERE tenant_id = a.tenant_id AND staff_id = p_staff AND ended_at IS NULL;
  INSERT INTO public.satusehat_practitioner_links (tenant_id, staff_id, ihs_practitioner_id, source, command_key, recorded_by, recorded_as)
  VALUES (a.tenant_id, p_staff, p_ihs, p_source, p_key, a.staff_id, a.role) RETURNING id INTO v_id;
  PERFORM public.audit_append('settings_change', 'satusehat_practitioner_link', v_id, 'success', 'satusehat_practitioner_set');
  FOR o IN SELECT x2.id FROM public.satusehat_outbox x2 JOIN public.satusehat_visit_context c ON c.tenant_id = x2.tenant_id AND c.visit_id = x2.visit_id
            WHERE x2.tenant_id = a.tenant_id AND x2.state = 'held' AND x2.hold_reason = 'practitioner_unresolved' AND c.doctor_staff_id = p_staff LOOP
    PERFORM public.satusehat_requeue(a.tenant_id, o.id);
  END LOOP;
  PERFORM public.satusehat_requeue_links(a.tenant_id, 'practitioner_unresolved', ARRAY(
    SELECT te.visit_id FROM public.treatment_executions te WHERE te.tenant_id = a.tenant_id AND te.performer_staff_id = p_staff
    UNION SELECT pr.visit_id FROM public.prescriptions pr WHERE pr.tenant_id = a.tenant_id AND pr.prescriber_staff_id = p_staff
    UNION SELECT d.visit_id FROM public.dispensings d WHERE d.tenant_id = a.tenant_id AND d.handed_by = p_staff AND d.visit_id IS NOT NULL));
  RETURN v_id;
END
$$;--> statement-breakpoint

-- The tenant's ICD-9 CM map for a service (plan §2): owner or facility head; configuration capability; keyed; the current row is ended and a
-- new one starts (never edited, never deleted); unvalidated until the owner-gated sandbox step. Visits waiting on that service's map are
-- requeued; an already sent revision is never re-sent under the new map (only a later revision pins it).
CREATE FUNCTION public.satusehat_code_map_set(p_key text, p_item uuid, p_code text, p_display text) RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  a record := public.satusehat_actor(ARRAY['owner','facility_head']);
  x public.satusehat_code_maps;
  v_id uuid;
BEGIN
  IF NOT public.tenant_capability('configuration') THEN
    RAISE EXCEPTION 'ERR_TENANT_SUSPENDED' USING ERRCODE = '42501';
  END IF;
  IF coalesce(p_key, '') !~ '^[A-Za-z0-9_.:-]{8,128}$' OR coalesce(p_code, '') !~ '^[0-9]{2}(\.[0-9]{1,2})?$'
     OR length(btrim(coalesce(p_display, ''))) NOT BETWEEN 2 AND 200 THEN
    RAISE EXCEPTION 'ERR_INVALID_INPUT: code map' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO x FROM public.satusehat_code_maps m WHERE m.tenant_id = a.tenant_id AND m.command_key = p_key;
  IF x.id IS NOT NULL THEN RETURN x.id; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.catalog_items i WHERE i.tenant_id = a.tenant_id AND i.id = p_item AND i.kind = 'service') THEN
    RAISE EXCEPTION 'ERR_NOT_FOUND: service not found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('satusehat_map:' || a.tenant_id::text || p_item::text, 0));
  UPDATE public.satusehat_code_maps SET effective_to = clock_timestamp() WHERE tenant_id = a.tenant_id AND item_id = p_item AND kind = 'icd9cm' AND effective_to IS NULL;
  INSERT INTO public.satusehat_code_maps (tenant_id, item_id, kind, code, display, command_key, mapped_by, mapped_as)
  VALUES (a.tenant_id, p_item, 'icd9cm', p_code, btrim(p_display), p_key, a.staff_id, a.role) RETURNING id INTO v_id;
  PERFORM public.audit_append('settings_change', 'satusehat_code_map', v_id, 'success', 'satusehat_code_map_set');
  PERFORM public.satusehat_requeue_links(a.tenant_id, 'terminology_unmapped', ARRAY(
    SELECT te.visit_id FROM public.treatment_executions te
      JOIN public.plan_items pi ON pi.tenant_id = te.tenant_id AND pi.id = te.plan_item_id
      JOIN public.catalog_versions cv ON cv.tenant_id = pi.tenant_id AND cv.id = pi.catalog_version_id
     WHERE te.tenant_id = a.tenant_id AND cv.item_id = p_item));
  RETURN v_id;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_code_map_set(text, uuid, text, text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION public.satusehat_code_map_set(text, uuid, text, text) TO clinic_app;
